mapper.select:
SELECT * FROM study_plan
WHERE user_id = #{userId} AND plan_date BETWEEN #{start} AND #{end}
ORDER BY plan_date ASC

mapper.update:
UPDATE study_plan
SET title = #{title}, category = #{category}, plan_date = #{planDate},
    duration_minutes = #{durationMinutes}, completed = #{completed}, notes = #{notes}
WHERE id = #{id} AND user_id = #{userId}
